import React, { useEffect, useMemo, useRef, useState } from 'react';
import { streamChat } from '../services/chatService';

const STREAMING_TYPES = new Set(['message', 'token', 'chunk', 'delta']);
const FINAL_TYPE = 'final';
const ERROR_TYPE = 'error';

function getInfoText(type, payload) {
  if (!payload || typeof payload !== 'object') return '';
  if (payload.message) return payload.message;
  if (payload.info) return payload.info;
  if (payload.step) return payload.step;
  return `[${type}] ${JSON.stringify(payload)}`;
}

export default function ChatbotWidget() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([
    {
      id: 'welcome',
      role: 'assistant',
      kind: 'final',
      text: 'Hi! Ask me anything about this registry. I can also show routing and intermediate processing steps.'
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [sessionId, setSessionId] = useState('');
  const pendingAssistantId = useRef(null);
  const abortRef = useRef(null);
  const scrollRef = useRef(null);

  const canSend = useMemo(() => input.trim().length > 0 && !isLoading, [input, isLoading]);

  useEffect(() => {
    const list = scrollRef.current;
    if (list) list.scrollTop = list.scrollHeight;
  }, [messages, isLoading, isOpen]);

  useEffect(() => {
    return () => {
      if (abortRef.current) {
        abortRef.current.abort();
      }
    };
  }, []);

  const appendMessage = (message) => {
    setMessages((prev) => [...prev, message]);
  };

  const updatePendingAssistant = (updater) => {
    const targetId = pendingAssistantId.current;
    if (!targetId) return;
    setMessages((prev) =>
      prev.map((msg) => (msg.id === targetId ? { ...msg, ...updater(msg) } : msg))
    );
  };

  const sendMessage = async () => {
    const text = input.trim();
    if (!text || isLoading) return;

    const userId = `user-${Date.now()}`;
    const assistantId = `assistant-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    pendingAssistantId.current = assistantId;
    setInput('');
    setIsLoading(true);

    appendMessage({ id: userId, role: 'user', kind: 'user', text });
    appendMessage({ id: assistantId, role: 'assistant', kind: 'stream', text: '', done: false });

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      await streamChat({
        message: text,
        sessionId,
        signal: controller.signal,
        onEvent: ({ type, payload, text: eventText }) => {
          const sid = payload?.session_id;
          if (sid) setSessionId(sid);

          if (type === ERROR_TYPE) {
            updatePendingAssistant(() => ({
              kind: 'error',
              text: payload?.message || 'Chat request failed.',
              done: true
            }));
            return;
          }

          if (type === FINAL_TYPE) {
            updatePendingAssistant((msg) => ({
              kind: 'final',
              text: payload?.answer || msg.text || '',
              done: true
            }));
            return;
          }

          if (STREAMING_TYPES.has(type)) {
            if (!eventText) return;
            updatePendingAssistant((msg) => ({
              kind: 'stream',
              text: `${msg.text || ''}${eventText}`,
              done: false
            }));
            return;
          }

          const infoText = getInfoText(type, payload);
          if (!infoText) return;
          appendMessage({
            id: `info-${Date.now()}-${Math.random().toString(16).slice(2)}`,
            role: 'system',
            kind: 'info',
            text: infoText
          });
        },
        onComplete: ({ sessionId: sid }) => {
          if (sid) setSessionId(sid);
        }
      });

      updatePendingAssistant((msg) => ({
        kind: msg.kind === 'stream' ? 'final' : msg.kind,
        done: true
      }));
    } catch (err) {
      if (err.name !== 'AbortError') {
        updatePendingAssistant(() => ({
          kind: 'error',
          text: err.message || 'Could not contact chat endpoint.',
          done: true
        }));
      }
    } finally {
      setIsLoading(false);
      pendingAssistantId.current = null;
      abortRef.current = null;
    }
  };

  const handleInputKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="chatbot-widget">
      {isOpen && (
        <section className="chatbot-panel" aria-label="Chat assistant">
          <header className="chatbot-header">
            <div>
              <div className="chatbot-title">Registry Assistant</div>
              <div className="chatbot-subtitle">Live reasoning events + final answer</div>
            </div>
            <button
              className="chatbot-close-btn"
              onClick={() => setIsOpen(false)}
              aria-label="Close chatbot"
            >
              ×
            </button>
          </header>

          <div className="chatbot-messages" ref={scrollRef}>
            {messages.map((msg) => (
              <div key={msg.id} className={`chatbot-msg chatbot-msg--${msg.kind} chatbot-msg--${msg.role}`}>
                {msg.text || (msg.kind === 'stream' ? '...' : '')}
              </div>
            ))}
            {isLoading && (
              <div className="chatbot-msg chatbot-msg--assistant chatbot-msg--typing">
                Thinking...
              </div>
            )}
          </div>

          <div className="chatbot-input-wrap">
            <textarea
              className="chatbot-input"
              rows={2}
              placeholder="Ask a question..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleInputKeyDown}
            />
            <button
              className="chatbot-send-btn"
              onClick={sendMessage}
              disabled={!canSend}
            >
              Send
            </button>
          </div>
        </section>
      )}

      <button
        className="chatbot-fab"
        onClick={() => setIsOpen((prev) => !prev)}
        aria-expanded={isOpen}
        aria-label={isOpen ? 'Close chatbot' : 'Open chatbot'}
      >
        {isOpen ? '−' : 'Chat'}
      </button>
    </div>
  );
}
